pub fn solve(input: Value) -> Value {
    let intervals: Vec<(i64, i64)> = input.as_array().unwrap()
        .iter()
        .map(|v| (v[0].as_i64().unwrap(), v[1].as_i64().unwrap()))
        .collect();

    let mut intervals = intervals;
    intervals.sort_by_key(|&(start, _)| start);

    let mut total_length = 0;
    let mut current_interval = None;

    for &(start, end) in &intervals {
        match current_interval {
            None => current_interval = Some((start, end)),
            Some((current_start, current_end)) => {
                if start < current_end {
                    current_interval = Some((current_start, end.max(current_end)));
                } else {
                    total_length += current_end - current_start;
                    current_interval = Some((start, end));
                }
            }
        }
    }

    if let Some((start, end)) = current_interval {
        total_length += end - start;
    }

    Value::from(total_length)
}
